#include <iostream>
using namespace std;
int main()
{
    int money;
    cin >> money;
    if (money > 1000)
    {
        if (money > 10000)
            cout << "У вас очень много денег." << endl;
        else
            cout << "У вас достаточно денег." << endl;
    }
    else
        cout << "У вас маловато денег." << endl;
    return 0;
}

#include <iostream>
using namespace std;
int main()
{
    int x;
    cout << "Введите балл за СОЧ" << endl;
    cin >> x;
    if (x >= 65)
        if (x >= 85)
            cout << "5" << endl;
        else cout << "4" << endl;
    else if (x <= 40)
        cout << "2" << endl;
    else
        cout << "3" << endl;
    return 0;
}

Чтобы программа принимала только корректные данные, после ввода можно проверить балл сложным условием и в ветке `else` записать определение оценки:

```cpp
if (score >= 0 && score <= 100) {
    if (score >= 90) cout << "Оценка: 5" << endl;
    else if (score >= 75) cout << "Оценка: 4" << endl;
    else if (score >= 60) cout << "Оценка: 3" << endl;
    else cout << "Оценка: 2" << endl;
} else {
    cout << "Некорректный ввод!" << endl;
}
```

Даны два целых числа a и b. Вывести «>», если a больше b; «<», если a меньше b; «=», если числа равны.

```cpp
if (a > b || a == b)
{
    if (a == b)
        cout << "=" << endl;
    else
        cout << ">" << endl;
}
else
    cout << "<" << endl;
```

#include <iostream>
using namespace std;
int main()
{
    int a, b, c;
