    {
        if (a == b && b == c && a == c)
            cout << "3" << endl;
        else
            cout << "2" << endl;
    }
    else
        cout << "0" << endl;
    return 0;
}

#include <iostream>
#include <cmath>
using namespace std;
int main()
{
    float x, y, pi = 3.14;
    cout << "Введите значение для x" << endl;
    cin >> x;
    if (x <= 0)
        y = 0;
    else if (x > 0 && x <= 1)
        y = pow(x, 3) + 5;
    else
        y = pow(x, 2) - sin(pi * x);
    cout << "y=" << y << endl;
    return 0;
}

Вложенные условия могут стоять в обеих ветках:

```cpp
if (num % 2 == 0) {
    cout << "Число четное";
    if (num % 3 == 0) cout << " и делится на 3." << endl;
    else cout << " и не делится на 3." << endl;
} else {
    cout << "Число нечетное";
    if (num % 3 == 0) cout << " и делится на 3." << endl;
    else cout << " и не делится на 3." << endl;
}
```

